'use client';

import { FormEvent, useCallback, useEffect, useMemo, useState } from 'react';
import type { CSSProperties, ReactNode } from 'react';
import { RequestDossierModal, type RequestDossier } from '@/components/requests/RequestDossierModal';

async function api<T>(path: string, init?: RequestInit): Promise<T> {
  const response = await fetch(path, { credentials: 'include', ...init });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data.error || `Could not complete ${init?.method || 'request'} (${response.status}).`);
  return data as T;
}

const card: CSSProperties = { background: '#fff', border: '1px solid #dce5f1', borderRadius: 14, padding: 18 };
const input: CSSProperties = { width: '100%', padding: '10px 12px', border: '1px solid #cbd5e1', borderRadius: 8, background: '#fff', color: '#14213d' };
const primary: CSSProperties = { padding: '9px 15px', border: '1px solid #ea580c', borderRadius: 8, background: 'linear-gradient(135deg, #f97316 0%, #ea580c 100%)', color: '#fff', fontWeight: 700, cursor: 'pointer', boxShadow: '0 2px 8px rgba(234, 88, 12, 0.28)' };
const secondary: CSSProperties = { padding: '8px 13px', border: '1px solid #fed7aa', borderRadius: 8, background: '#fff', color: '#334155', fontWeight: 650, cursor: 'pointer' };
const fmt = (minor: number | bigint | null | undefined) => new Intl.NumberFormat('en-NG', { style: 'currency', currency: 'NGN', maximumFractionDigits: 0 }).format(Number(minor || 0) / 100);
const date = (value?: string | Date | null) => value ? new Date(value).toLocaleDateString('en-NG', { day: '2-digit', month: 'short', year: 'numeric' }) : '—';
const errorText = (error: unknown) => error instanceof Error ? error.message : 'Something went wrong.';

function PageHeading({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: ReactNode }) {
  return <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', gap: 16, marginBottom: 20, flexWrap: 'wrap' }}><div><div style={{ color: '#8292aa', fontSize: 11, fontWeight: 800, letterSpacing: '.16em', textTransform: 'uppercase' }}>{eyebrow}</div><h1 style={{ margin: '7px 0', color: '#101e3b', fontSize: 28, letterSpacing: '-.04em' }}>{title}</h1><p style={{ margin: 0, color: '#73839d', fontSize: 14 }}>{description}</p></div>{action}</header>;
}

function StateMessage({ value, retry }: { value: string; retry?: () => void }) {
  return <div style={{ ...card, margin: '14px 0', color: '#a33b31', background: '#fff8f6' }}>{value}{retry && <button style={{ ...secondary, marginLeft: 12 }} onClick={retry}>Try again</button>}</div>;
}

type AccountabilityCase = {
  id: string; status: string; dueAt: string; requiredDeliverables: string; closureNotes?: string | null;
  owner: { id: string; legalName: string; workEmail: string };
  request: { id: string; requestNumber: string; title: string; amountMinor: number; currency: string; subsidiary: { legalName: string }; requester: { legalName: string; workEmail: string }; disbursements: { id: string; amountMinor: number; paidAt: string; externalReference: string; receipt?: { id: string; fileName: string } | null }[] };
  attachments: { id: string; fileName: string; contentType: string; uploadedAt: string; url: string }[];
};

export function AccountabilityModule({ setNotice }: { setNotice: (message: string) => void }) {
  const [cases, setCases] = useState<AccountabilityCase[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const [query, setQuery] = useState(''); const [selected, setSelected] = useState<AccountabilityCase | null>(null); const [notes, setNotes] = useState(''); const [working, setWorking] = useState(false);
  const load = useCallback(async () => { setLoading(true); setError(''); try { await api('/api/accountability', { method: 'POST' }); const data = await api<{ cases: AccountabilityCase[] }>('/api/accountability'); setCases(data.cases); } catch (e) { setError(errorText(e)); } finally { setLoading(false); } }, []);
  useEffect(() => { void load(); }, [load]);
  const filtered = cases.filter(c => `${c.request.requestNumber} ${c.request.title} ${c.owner.legalName} ${c.request.subsidiary.legalName} ${c.status}`.toLowerCase().includes(query.toLowerCase()));
  const closeCase = async () => { if (!selected) return; setWorking(true); try { await api('/api/accountability/close', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ caseId: selected.id, decision: 'CLOSE', closureNotes: notes }) }); setNotice(`${selected.request.requestNumber} accountability case closed.`); setSelected(null); setNotes(''); await load(); } catch (e) { setError(errorText(e)); } finally { setWorking(false); } };
  return <><PageHeading eyebrow="ACCOUNTABILITY" title="Accountability closure" description="Review evidence submitted by staff, verify the spend, and close completed cases." action={<button style={secondary} onClick={() => void load()}>↻ Refresh</button>}/><div style={{ display: 'grid', gridTemplateColumns: 'repeat(4,minmax(130px,1fr))', gap: 12, marginBottom: 16 }}>{[['OPEN',cases.filter(c=>c.status==='OPEN').length],['EVIDENCE SUBMITTED',cases.filter(c=>c.status==='EVIDENCE_SUBMITTED').length],['VERIFIED',cases.filter(c=>c.status==='VERIFIED').length],['CLOSED',cases.filter(c=>c.status==='CLOSED').length]].map(([label,value])=><article style={card} key={String(label)}><small style={{ color: '#8090a8', fontWeight: 800 }}>{label}</small><div style={{ fontSize: 26, fontWeight: 800, color: '#13244a', marginTop: 6 }}>{value}</div></article>)}</div><section style={card}><input style={{ ...input, maxWidth: 440, marginBottom: 14 }} value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search request, staff, company, or status"/>{loading?<p>Loading cases…</p>:error?<StateMessage value={error} retry={()=>void load()}/>:filtered.length===0?<p style={{ color: '#7889a3' }}>No accountability cases match this view.</p>:filtered.map(c=><button key={c.id} onClick={()=>{setSelected(c);setNotes('')}} style={{ width: '100%', textAlign: 'left', padding: '15px 8px', display: 'grid', gridTemplateColumns: 'minmax(240px,2fr) 1fr 1fr 1fr auto', gap: 14, alignItems: 'center', border: 0, borderBottom: '1px solid #e8edf4', background: '#fff', cursor: 'pointer', color: '#263955' }}><span><b>{c.request.requestNumber} · {c.request.title}</b><small style={{ display: 'block', marginTop: 5, color: '#7788a2' }}>{c.request.subsidiary.legalName} · {c.owner.legalName}</small></span><span>{fmt(c.request.amountMinor)}</span><span>Due {date(c.dueAt)}</span><b>{c.status.replaceAll('_',' ')}</b><span>Details →</span></button>)}</section>{selected&&<div role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)setSelected(null)}} style={{ position:'fixed',inset:0,zIndex:1000,background:'rgba(5,18,45,.55)',display:'grid',placeItems:'center',padding:18 }}><section role="dialog" aria-modal="true" style={{...card,width:'min(760px,100%)',maxHeight:'88vh',overflow:'auto'}}><header style={{display:'flex',justifyContent:'space-between',gap:16}}><div><small style={{color:'#ea580c',fontWeight:800}}>{selected.request.requestNumber} · {selected.status}</small><h2 style={{margin:'6px 0 12px',fontSize:22}}>{selected.request.title}</h2></div><button style={secondary} onClick={()=>setSelected(null)}>Close</button></header><p><b>Requester:</b> {selected.request.requester.legalName} · <b>Owner:</b> {selected.owner.legalName}</p><p><b>Company:</b> {selected.request.subsidiary.legalName} · <b>Approved:</b> {fmt(selected.request.amountMinor)} · <b>Due:</b> {date(selected.dueAt)}</p><h3>Payment record</h3>{selected.request.disbursements.map(d=><div key={d.id} style={{...card,background:'#f7f9fc',marginBottom:8}}>{fmt(d.amountMinor)} · {d.externalReference} · {date(d.paidAt)} {d.receipt&&<>· <a href={`/api/receipts/${d.receipt.id}`} target="_blank">{d.receipt.fileName}</a></>}</div>)}<h3>Required evidence</h3><p>{selected.requiredDeliverables}</p><h3>Staff uploads</h3>{selected.attachments.length?selected.attachments.map(a=><p key={a.id}><a href={a.url} target="_blank">{a.fileName}</a> · {date(a.uploadedAt)}</p>):<p style={{color:'#7889a3'}}>No evidence has been submitted yet.</p>}{selected.status!=='CLOSED'&&<><label style={{display:'block',fontWeight:700,marginTop:16}}>Closure notes<textarea style={{...input,display:'block',marginTop:6,minHeight:80}} value={notes} onChange={e=>setNotes(e.target.value)} placeholder="Record what was checked and any variance."/></label><button style={{...primary,marginTop:12}} onClick={()=>void closeCase()} disabled={working||selected.attachments.length===0}>{working?'Closing…':'Verify evidence & close case'}</button>{selected.attachments.length===0&&<small style={{display:'block',marginTop:8,color:'#9a5b08'}}>The case can be closed after staff submit evidence.</small>}</>}</section></div>}</>;
}

type ReceiptRow = { id: string; fileName: string; fileUrl: string; fileAvailable: boolean; sha256: string; mimeType: string; uploadedAt: string; disbursement: { amountMinor: number; currency: string; externalReference: string; bankName: string; paidAt: string; request?: { requestNumber: string; title: string; subsidiary: { legalName: string }; requester: { legalName: string } } | null; payrollItem?: { employee: { legalName: string }; batch: { period: { year: number; month: number } } } | null; recordedBy: { legalName: string } } };

export function ReceiptArchiveModule({ setNotice }: { setNotice: (message: string) => void }) {
  const [rows,setRows]=useState<ReceiptRow[]>([]);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const [query,setQuery]=useState('');
  const load=useCallback(async()=>{setLoading(true);setError('');try{const data=await api<{receipts:ReceiptRow[]}>('/api/receipts');setRows(data.receipts)}catch(e){setError(errorText(e))}finally{setLoading(false)}},[]);useEffect(()=>{void load()},[load]);
  const filtered=rows.filter(r=>`${r.fileName} ${r.disbursement.externalReference} ${r.disbursement.request?.requestNumber||''} ${r.disbursement.request?.title||''} ${r.disbursement.payrollItem?.employee.legalName||''}`.toLowerCase().includes(query.toLowerCase()));
  return <><PageHeading eyebrow="PAYMENT EVIDENCE" title="Receipt archive" description="Search uploaded bank slips and payroll receipts, then open the original secure file." action={<button style={secondary} onClick={()=>void load()}>↻ Refresh</button>}/><section style={card}><input style={{...input,maxWidth:440,marginBottom:14}} value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search file, request, reference, or employee"/>{loading?<p>Loading receipts…</p>:error?<StateMessage value={error} retry={()=>void load()}/>:filtered.length===0?<p style={{color:'#7889a3'}}>No payment receipts have been recorded yet.</p>:<div style={{overflowX:'auto'}}><table style={{width:'100%',borderCollapse:'collapse',minWidth:760}}><thead><tr>{['Receipt','Request / recipient','Subsidiary','Amount','Uploaded','Integrity',''].map(x=><th key={x} style={{textAlign:'left',padding:10,color:'#71819a',fontSize:12}}>{x}</th>)}</tr></thead><tbody>{filtered.map(r=><tr key={r.id} style={{borderTop:'1px solid #e8edf4'}}><td style={{padding:10}}><b>{r.fileName}</b><small style={{display:'block',color:'#8593a8'}}>{r.mimeType}</small></td><td style={{padding:10}}>{r.disbursement.request?<><b>{r.disbursement.request.requestNumber}</b><small style={{display:'block',color:'#8593a8'}}>{r.disbursement.request.title}</small></>:r.disbursement.payrollItem?.employee.legalName||'Payroll payment'}</td><td style={{padding:10}}>{r.disbursement.request?.subsidiary.legalName||'Group payroll'}</td><td style={{padding:10}}>{fmt(r.disbursement.amountMinor)}</td><td style={{padding:10}}>{date(r.uploadedAt)}</td><td style={{padding:10}} title={r.sha256}>{r.sha256.slice(0,10)}…</td><td style={{padding:10}}>{r.fileAvailable?<a href={`/api/receipts/${r.id}`} target="_blank" rel="noreferrer" onClick={()=>setNotice(`Opening ${r.fileName}.`)}>Open receipt ↗</a>:<span title="This older record has no stored receipt file.">File unavailable</span>}</td></tr>)}</tbody></table></div>}</section></>;
}

type EvidenceCase = Pick<AccountabilityCase,'id'|'status'|'dueAt'|'requiredDeliverables'|'request'> & { owner: AccountabilityCase['owner'] };

export function ProofDeliverablesModule({ setNotice }: { setNotice: (message: string) => void }) {
  const [cases,setCases]=useState<EvidenceCase[]>([]);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const [caseId,setCaseId]=useState('');const [file,setFile]=useState<File|null>(null);const [notes,setNotes]=useState('');const [saving,setSaving]=useState(false);
  const load=useCallback(async()=>{setLoading(true);setError('');try{await api('/api/accountability',{method:'POST'}).catch(()=>undefined);const data=await api<{cases:EvidenceCase[]}>('/api/accountability');setCases(data.cases.filter(c=>c.status!=='CLOSED'))}catch(e){setError(errorText(e))}finally{setLoading(false)}},[]);useEffect(()=>{void load()},[load]);
  const submit=async(e:FormEvent)=>{e.preventDefault();if(!caseId||!file)return;setSaving(true);const form=new FormData();form.set('caseId',caseId);form.set('notes',notes);form.set('file',file);try{await api('/api/accountability/evidence',{method:'POST',body:form});setNotice('Evidence submitted and the verifier has been notified.');setCaseId('');setFile(null);setNotes('');await load()}catch(e){setError(errorText(e))}finally{setSaving(false)}};
  return <><PageHeading eyebrow="STAFF SUBMISSIONS" title="Proof & deliverables" description="As the requester, attach invoices, waybills, completion evidence, or other deliverables after payment."/><section style={{...card,marginBottom:16}}><h2 style={{marginTop:0,fontSize:18}}>Submit evidence for your paid request</h2>{loading?<p>Loading your open requests…</p>:error?<StateMessage value={error} retry={()=>void load()}/>:cases.length===0?<p style={{color:'#7889a3'}}>You have no paid requests waiting for evidence.</p>:<form onSubmit={submit} style={{display:'grid',gap:12,maxWidth:760}}><label style={{fontWeight:700}}>Your request<select style={{...input,display:'block',marginTop:5}} required value={caseId} onChange={e=>setCaseId(e.target.value)}><option value="">Choose one of your paid requests…</option>{cases.map(c=><option key={c.id} value={c.id}>{c.request.requestNumber} · {c.request.title} · due {date(c.dueAt)}</option>)}</select></label>{caseId&&<p style={{margin:0,color:'#70819b'}}>Required: {cases.find(c=>c.id===caseId)?.requiredDeliverables}</p>}<label style={{fontWeight:700}}>Evidence file<input style={{...input,display:'block',marginTop:5}} required type="file" accept=".pdf,.png,.jpg,.jpeg,.webp" onChange={e=>setFile(e.target.files?.[0]||null)}/><small style={{fontWeight:400,color:'#7d8ba1'}}>PDF or image, up to 10 MB.</small></label><label style={{fontWeight:700}}>Notes<textarea style={{...input,display:'block',marginTop:5,minHeight:78}} value={notes} onChange={e=>setNotes(e.target.value)} placeholder="Briefly explain what this file proves." maxLength={1000}/></label><div><button style={primary} disabled={saving||!file}>{saving?'Uploading…':'Submit evidence'}</button></div></form>}</section><section style={card}><h2 style={{marginTop:0,fontSize:18}}>Your requests awaiting close-out</h2>{cases.map(c=><div key={c.id} style={{padding:'12px 0',borderTop:'1px solid #e8edf4'}}><b>{c.request.requestNumber} · {c.request.title}</b><span style={{marginLeft:10,color:'#71819a'}}>{c.status.replaceAll('_',' ')} · {c.request.subsidiary.legalName}</span></div>)}</section></>;
}

type Task = { id: string; description: string; dueAt: string; status: string; responseNotes?: string | null; assignee: { id: string; legalName: string; role: string }; accountabilityCase?: { request: { requestNumber: string; title: string } } | null; channel?: { request: { requestNumber: string; title: string } } | null };
type StaffOption = { id: string; legalName: string; role: string };

export function FollowUpTasksModule({ setNotice }: { setNotice: (message: string) => void }) {
  const [tasks,setTasks]=useState<Task[]>([]);const [staff,setStaff]=useState<StaffOption[]>([]);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const [creating,setCreating]=useState(false);const [description,setDescription]=useState('');const [dueAt,setDueAt]=useState('');const [assigneeId,setAssigneeId]=useState('');const [saving,setSaving]=useState(false);const [filter,setFilter]=useState('OPEN');
  const load=useCallback(async()=>{setLoading(true);setError('');try{const [taskData,staffData]=await Promise.all([api<{tasks:Task[]}>('/api/tasks'),api<{employees:StaffOption[]}>('/api/staff')]);setTasks(taskData.tasks);setStaff(staffData.employees);if(!assigneeId)setAssigneeId(staffData.employees[0]?.id||'')}catch(e){setError(errorText(e))}finally{setLoading(false)}},[assigneeId]);useEffect(()=>{void load()},[load]);
  const save=async(e:FormEvent)=>{e.preventDefault();setSaving(true);try{await api('/api/tasks',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({description,dueAt:new Date(dueAt).toISOString(),assigneeId})});setCreating(false);setDescription('');setDueAt('');setNotice('Follow-up task assigned.');await load()}catch(e){setError(errorText(e))}finally{setSaving(false)}};
  const complete=async(task:Task)=>{try{await api(`/api/tasks/${task.id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:'COMPLETED'})});setNotice('Follow-up task completed.');await load()}catch(e){setError(errorText(e))}};
  const visible=tasks.filter(t=>filter==='ALL'||(filter==='OPEN'?t.status!=='COMPLETED':t.status===filter));
  return <><PageHeading eyebrow="ACCOUNTABILITY WORK QUEUE" title="Follow-up tasks" description="Assign and track evidence, clarification, and payment-confirmation follow-ups." action={<button style={primary} onClick={()=>setCreating(v=>!v)}>＋ New task</button>}/><div style={{display:'flex',gap:8,marginBottom:14}}>{['OPEN','OVERDUE','COMPLETED','ALL'].map(x=><button key={x} style={filter===x?primary:secondary} onClick={()=>setFilter(x)}>{x==='OPEN'?'Open':x==='ALL'?'All tasks':x.charAt(0)+x.slice(1).toLowerCase()}</button>)}<button style={{...secondary,marginLeft:'auto'}} onClick={()=>void load()}>↻ Refresh</button></div>{creating&&<form onSubmit={save} style={{...card,marginBottom:14,display:'grid',gridTemplateColumns:'2fr 1fr 1fr auto',gap:10,alignItems:'end'}}><label style={{fontWeight:700}}>Task<input style={{...input,display:'block',marginTop:5}} required value={description} onChange={e=>setDescription(e.target.value)} placeholder="e.g. Confirm delivery note"/></label><label style={{fontWeight:700}}>Due date<input style={{...input,display:'block',marginTop:5}} required type="date" value={dueAt} onChange={e=>setDueAt(e.target.value)}/></label><label style={{fontWeight:700}}>Assign to<select style={{...input,display:'block',marginTop:5}} value={assigneeId} onChange={e=>setAssigneeId(e.target.value)}>{staff.map(s=><option key={s.id} value={s.id}>{s.legalName} · {s.role}</option>)}</select></label><button style={primary} disabled={saving}>{saving?'Saving…':'Assign'}</button></form>}{loading?<p>Loading tasks…</p>:error?<StateMessage value={error} retry={()=>void load()}/>:<section style={card}>{visible.length===0?<p style={{color:'#7889a3'}}>No tasks in this queue.</p>:visible.map(t=>{const req=t.accountabilityCase?.request||t.channel?.request;const overdue=t.status!=='COMPLETED'&&new Date(t.dueAt)<new Date();return <div key={t.id} style={{display:'grid',gridTemplateColumns:'minmax(240px,2fr) 1fr 1fr 1fr auto',gap:12,alignItems:'center',padding:'13px 2px',borderBottom:'1px solid #e8edf4'}}><span><b>{t.description}</b><small style={{display:'block',marginTop:4,color:'#7d8ba1'}}>{req?`${req.requestNumber} · ${req.title}`:'General follow-up'}{t.responseNotes?` · ${t.responseNotes}`:''}</small></span><span>{t.assignee.legalName}<small style={{display:'block',color:'#8794a8'}}>{t.assignee.role}</small></span><span>{date(t.dueAt)}</span><b style={{color:overdue?'#b42318':t.status==='COMPLETED'?'#008567':'#9a6200'}}>{overdue?'OVERDUE':t.status}</b>{t.status!=='COMPLETED'&&<button style={secondary} onClick={()=>void complete(t)}>Mark complete</button>}</div>})}</section>}</>;
}

type Staff = { id: string; legalName: string; workEmail: string; role: string; status: string; employeeNumber: string; phone?: string | null; assignments: { subsidiary: { legalName: string }; department?: { name: string } | null; positionName: string }[]; employmentAgreements: { compensations: { grossMinor: number; currency: string; recurrence: string; version: number; changeType?: string | null; changeReason?: string | null; effectiveFrom: string }[] }[] };
